'use strict';
let resumeProfile=null,resumeResult=null,resumeGapReport=null,resumeJobId='',resumeBusy=false;
const exampleResume={version:1,name:'Your Name',contacts:['you@example.com','github.com/your-handle'],source_label:'My full resume',full_details:'',sections:[{title:'Education',kind:'education',entries:[{title:'University',subtitle:'Degree',dates:'Start - End',location:'City',bullets:[]}]},{title:'Experience',kind:'experience',entries:[{title:'Job title | Technologies',subtitle:'Employer',dates:'Start - End',location:'City',bullets:['Replace this with your exact achievement, including its original metric and qualifier.'],groups:[]}]},{title:'Projects',kind:'projects',entries:[{title:'Project | Technologies',subtitle:'',dates:'',location:'',bullets:['Describe the work you actually completed.']}]},{title:'Technical Skills',kind:'skills',entries:[{title:'Languages',subtitle:'',dates:'',location:'',bullets:['List only your actual skills.']}]}]};
function renderResume(){
 const jobs=state.jobs.slice().sort((a,b)=>({strong:0,possible:1}[a.fit_band]??2)-({strong:0,possible:1}[b.fit_band]??2)||a.company.localeCompare(b.company));
 if(!jobs.some(j=>j.id===resumeJobId))resumeJobId=jobs.find(j=>j.status_source!=='not_listed')?.id||jobs[0]?.id||'';
 const selected=jobs.find(j=>j.id===resumeJobId);
 $('#app').innerHTML=`<section class="card"><h2>Resume & cover letter studio</h2><p>Choose a job and generate LaTeX in the reference resume's single-column format. Tailoring selects and reorders your exact statements. Metrics, estimates, dates and employers stay attached to their source.</p><p class="notice">Review every draft before sending. Topic overlap is not an ATS score. More detailed evidence can be added below; missing evidence is not proof of a missing skill.</p><details><summary>Edit or import your full resume profile</summary><p>Import a JSON profile or edit it here. Add entries, bullets and optional <code>groups: [{"heading":"Subheading","bullets":["Exact source statement"]}]</code> under any work/project entry. Use full_details for extra context in gap analysis; move achievements into structured entries to include them in documents. No data is sent to an AI service.</p><input id="resume-import" type="file" accept=".json,application/json" aria-label="Import resume profile JSON"><label>Resume profile JSON<textarea id="resume-profile" rows="20" spellcheck="false">${esc(JSON.stringify(resumeProfile||exampleResume,null,2))}</textarea></label><button id="resume-save">Save full resume profile</button><button id="resume-export">Export profile JSON</button></details></section>
 <section class="card section"><label>Target job<select id="resume-job">${jobs.map(j=>`<option value="${esc(j.id)}" ${j.id===resumeJobId?'selected':''}>${esc(j.company+' — '+j.title+' ['+j.status_source+']')}</option>`).join('')}</select></label><p>${selected?link(selected.source_url,'Open original JD'): 'No jobs saved yet. Refresh configured boards or track a LinkedIn result.'}</p><label>Full JD (paste if absent or incomplete)<textarea id="resume-jd" rows="9">${esc(selected?.full_description||'')}</textarea></label><p class="small muted">A keyword summary is insufficient for drafting. Save pasted changes before generating.</p><button id="resume-save-jd">Save full JD</button><label>Maximum bullets per work/project entry <input id="resume-limit" type="number" min="1" max="12" value="4"></label><button id="resume-generate" class="primary">Generate resume & cover letter</button><p id="resume-error" role="status"></p></section>
 <section id="resume-output" class="section"></section>`;
 $('#resume-job').onchange=e=>{resumeJobId=e.target.value;resumeResult=null;renderResume()};
 $('#resume-save').onclick=()=>resumeAction(async()=>{const result=await api('/api/resume/profile',{profile:JSON.parse($('#resume-profile').value)});resumeProfile=result.profile;$('#resume-profile').value=JSON.stringify(resumeProfile,null,2);resumeResult=null;resumeGapReport=null;$('#resume-output').innerHTML='';toast('Full profile saved locally')});
 $('#resume-export').onclick=()=>download('resume-profile.json',$('#resume-profile').value,'application/json');
 $('#resume-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1900000)throw Error('Profile is too large');const text=await file.text();JSON.parse(text);$('#resume-profile').value=text;toast('Imported into editor. Review and save to use it.')}catch(error){toast(error.message)}};
 $('#resume-save-jd').onclick=()=>resumeAction(async()=>{const full_description=$('#resume-jd').value;await api('/api/resume/jd',{job_id:resumeJobId,full_description});selected.full_description=full_description;resumeResult=null;resumeGapReport=null;$('#resume-output').innerHTML='';toast('Full JD saved locally')});
 $('#resume-generate').onclick=()=>resumeAction(async()=>{if($('#resume-jd').value!==(selected?.full_description||''))throw Error('Save the edited JD first');if(JSON.stringify(JSON.parse($('#resume-profile').value))!==JSON.stringify(resumeProfile))throw Error('Save your edited profile first');resumeResult=await api('/api/resume/generate',{job_id:resumeJobId,max_bullets:Number($('#resume-limit').value)});showResumeOutput()});
 if(resumeResult)showResumeOutput();
 if(!resumeProfile)api('/api/resume/profile').then(r=>{resumeProfile=r.profile;if(tab==='resume'&&r.profile&&$('#resume-profile').value===JSON.stringify(exampleResume,null,2))$('#resume-profile').value=JSON.stringify(r.profile,null,2)}).catch(e=>toast(e.message));
}
async function resumeAction(fn){if(resumeBusy)return;resumeBusy=true;$('#resume-error').textContent='Working locally…';try{await fn();$('#resume-error').textContent='Saved / ready'}catch(e){$('#resume-error').textContent=e.message}finally{resumeBusy=false}}
function showResumeOutput(){const r=resumeResult;$('#resume-output').innerHTML=`<article class="card"><h3>Application drafts</h3><p>Download the LaTeX files, then compile using the README instructions or Overleaf with pdfLaTeX. The text preview verifies content; inspect the compiled PDF for page breaks.</p><div class="row"><button id="dl-resume">Resume .tex</button><button id="dl-cover">Cover letter .tex</button><button id="dl-text">Plain text</button><button id="dl-audit">Evidence audit</button></div><details open><summary>Resume preview</summary><pre style="white-space:pre-wrap">${esc(r.resume_text)}</pre></details><details><summary>Cover letter preview</summary><pre style="white-space:pre-wrap">${esc(r.cover_letter_text)}</pre></details><p class="notice">Evidence not found: ${esc(r.analysis.missing.join(', ')||'None among detected topics')}. Listed without a matching achievement: ${esc(r.analysis.listed_only.join(', ')||'None')}.</p></article>`;
 $('#dl-resume').onclick=()=>download('resume.tex',r.resume_tex,'application/x-tex');$('#dl-cover').onclick=()=>download('cover-letter.tex',r.cover_letter_tex,'application/x-tex');$('#dl-text').onclick=()=>download('application-drafts.txt',r.resume_text+'\n\n'+r.cover_letter_text,'text/plain');$('#dl-audit').onclick=()=>download('evidence-audit.json',JSON.stringify({audit:r.audit,analysis:r.analysis},null,2),'application/json');}
function renderLiveGaps(){
 $('#app').innerHTML=`<section class="card"><h2>Resume evidence across prospective jobs</h2><p>Uses the saved full resume profile against every saved job. Includes previously reviewed strong/possible prospects plus provisional matches with at least three detected JD topics and 60% source mention overlap. Closed or passed roles are excluded. Full-JD and summary-only results are kept distinct.</p><button id="gap-refresh" class="primary">Recalculate gaps</button><button id="gap-studio">Open resume & cover letter studio</button><p id="gap-status" role="status"></p></section><div id="gap-results" class="section"></div>`;
 $('#gap-studio').onclick=()=>{tab='resume';render()};$('#gap-refresh').onclick=async()=>{const button=$('#gap-refresh');button.disabled=true;$('#gap-status').textContent='Comparing saved evidence…';try{resumeGapReport=await api('/api/resume/gaps');if(tab==='gaps'){showLiveGaps();$('#gap-status').textContent='Updated '+formatDate(resumeGapReport.generated_at)}}catch(e){if(tab==='gaps')$('#gap-status').textContent=e.message}finally{button.disabled=false}};
 if(resumeGapReport)showLiveGaps();else $('#gap-refresh').onclick();
}
function showLiveGaps(){const r=resumeGapReport;$('#gap-results').innerHTML=`<section class="card"><h3>${r.prospects} prospects from ${r.jobs_scanned} saved jobs</h3><p>${r.full_jd_count} have full JDs; ${r.prospects-r.full_jd_count} are incomplete summary comparisons. Source: ${esc(r.profile_source)}.</p><p class="notice">A keyword mention does not establish mastery or satisfy years of experience. Preferred, alternative and negated requirements need human review. These counts describe this saved sample, not the job market.</p><h3>Most frequent missing evidence</h3><p>${esc(r.priority_gaps.map(g=>g.skill+' ('+g.jobs+' jobs)').join(', ')||'No missing detected topics')}</p><button id="gap-download">Download full gap report</button></section>${r.jobs.map(j=>`<article class="card section"><h3>${esc(j.company)} — ${esc(j.title)}</h3><p>${esc(j.coverage==='full_jd'?'Full JD':'Summary only — incomplete')} · ${j.overlap_percent??'N/A'}% topic mention overlap · ${esc(j.status_source)}</p><p class="small muted">${esc(j.selection)} · JD checked ${esc(formatDate(j.jd_checked_at))}</p><p><strong>Evidence missing:</strong> ${esc(j.missing.join(', ')||'None among detected topics')}</p><p><strong>Listed only:</strong> ${esc(j.listed_only.join(', ')||'None')}</p><details><summary>Requirement excerpts and exact resume evidence</summary>${j.topics.map(t=>`<p><strong>${esc(t.skill)} — ${esc(t.status)}</strong><br>JD: ${esc(t.jd_excerpt)}<br>${t.evidence.map(e=>esc(e.context+': '+e.text)).join('<br>')||'No source evidence found'}</p>`).join('')}<h4>Other requirements to review</h4><ul>${list(j.review_requirements)}</ul></details>${link(j.source_url,'Original JD')} <button data-tailor="${esc(j.job_id)}">Tailor application</button></article>`).join('')}`;$('#gap-download').onclick=()=>download('resume-gap-analysis.json',JSON.stringify(r,null,2),'application/json');document.querySelectorAll('[data-tailor]').forEach(b=>b.onclick=()=>{resumeJobId=b.dataset.tailor;resumeResult=null;tab='resume';render()});}
